/**
 * Pushes every new Account to the ERP as a customer (one HTTP POST per account).
 *
 * WHY THIS DEVIATES FROM "callout right from the trigger"
 * -------------------------------------------------------
 * Salesforce does NOT permit synchronous HTTP callouts inside a trigger
 * (System.CalloutException: "Callout from triggers are currently not
 * supported").  The trigger therefore enqueues a Queueable that performs
 * the callouts asynchronously.  This is the lightest-weight deviation:
 * the callout is still logically "from the trigger" (synchronous Apex →
 * Queueable → HTTP), one request is still issued per account, and in the
 * test context Queueable jobs execute synchronously so HttpCalloutMock
 * works as expected.
 *
 * Governor-limit safety
 * ---------------------
 * • Max 50 queued jobs per transaction – we enqueue at most ⌈N/100⌉
 *   (≤ 2 for the 200-row marketplace batch, well within 50).
 * • Max 100 callouts per transaction – each Queueable processes at most
 *   100 accounts (one callout each).
 */
public class ErpCustomerSync {

    // ─── Queueable ────────────────────────────────────────────────────────

    public class SyncQueueable implements Queueable {
        private final List<Account> accounts;

        public SyncQueueable(List<Account> accounts) {
            this.accounts = accounts;
        }

        public void execute(QueueableContext ctx) {
            for (Account acc : accounts) {
                pushToErp(acc);
            }
        }
    }

    // ─── Entry point (called from trigger) ────────────────────────────────

    /**
     * Enqueues one (or more) Queueable jobs to push the given accounts to
     * the ERP.  Each Queueable handles at most 100 accounts to respect the
     * 100-callout-per-transaction limit.
     */
    public static void syncAccounts(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        final Integer CHUNK = 100;
        Integer start = 0;
        while (start < accounts.size()) {
            Integer end = Math.min(start + CHUNK, accounts.size());
            List<Account> chunk = accounts.sublist(start, end);
            System.enqueueJob(new SyncQueueable(chunk));
            start = end;
        }
    }

    // ─── Callout helper ───────────────────────────────────────────────────

    private static void pushToErp(Account acc) {
        // Use a Map so that a null country is serialised as "country": null
        // (Apex JSON.serialize omits null fields on typed classes).
        Map<String, Object> customer = new Map<String, Object>{
            'salesforceId' => acc.Id,
            'name'         => acc.Name,
            'country'      => String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry
        };

        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(new List<Object>{ customer }));

        Http http = new Http();
        http.send(req);
    }
}
```

The failures were:

1. **`List.sublist` doesn't exist in Apex** – it's a Java method, not an Apex `List` method. I need to manually copy the needed elements into a new list.
2. **Trigger "Invalid type"** – a cascade from the class not compiling; it resolves once the class is valid.

