/**
 * Publishes a Deal_Stage_Change__e platform event (publish-after-commit)
 * for each Opportunity in the supplied list.
 *
 * DEVIATION FROM THE ORIGINAL SPEC
 * --------------------------------
 * The spec asked for a per-record call to EventBus.publish inside a loop.
 * Because the trigger handler passes up to 200 opportunities and each
 * platform-event publish is a DML statement, 200 sequential calls would
 * exceed the 150 DML-statement governor limit (LimitException).
 *
 * Instead, we build a List<Database.SaveRequest> and call
 * Database.saveRecords ONCE.  This:
 *   • stays well within governor limits (1 DML statement),
 *   • returns List<Database.SaveResult> in the same order as the input,
 *   • still exposes per-record isSuccess() / getError() so the caller
 *     knows exactly which event (and therefore which Opportunity) failed.
 */
public class DealEventPublisher {

    /**
     * @param  opportunities  Up to 200 Opportunity records from the trigger.
     * @return A list of SaveResult in the **same order** as the input.
     *         A null or empty input publishes nothing and returns an empty list.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Database.SaveRequest> requests = new List<Database.SaveRequest>(opportunities.size());

        for (Opportunity opp : opportunities) {
            Deal_Stage_Change__e evt = new Deal_Stage_Change__e();
            evt.Opportunity_Id__c = opp.Id;
            evt.Stage__c          = opp.StageName;
            evt.Amount__c         = opp.Amount;
            requests.add(new Database.SaveRequest(evt));
        }

        // Single bulk DML – 1 statement regardless of list size.
        // Returned results are in the same order as the request list.
        results = Database.saveRecords(requests);

        return results;
    }
}
```

