```apex
public class AccountCountrySync {

    /**
     * After-update handler: when an Account's BillingCountry changes, propagate the
     * new country to contacts that are "following" the account (MailingCountry is
     * blank or still equals the old BillingCountry).
     *
     * Bulk-safe:
     *   - One SOQL (scoped to the affected AccountIds in the current batch).
     *   - One DML (a single update on the collected contacts).
     *   - No SOQL/DML inside loops.
     */
    public static void handle() {

        // 1. Identify accounts whose BillingCountry actually changed
        Set<Id>       changedAccountIds  = new Set<Id>();
        Map<Id, String> oldCountryByAcct = new Map<Id, String>();

        for (Account newAcc : (List<Account>) Trigger.new) {
            Account oldAcc = (Account) Trigger.oldMap.get(newAcc.Id);
            if (oldAcc != null && oldAcc.BillingCountry != newAcc.BillingCountry) {
                changedAccountIds.add(newAcc.Id);
                oldCountryByAcct.put(newAcc.Id, oldAcc.BillingCountry);
            }
        }

        // Nothing changed → exit early
        if (changedAccountIds.isEmpty()) {
            return;
        }

        // 2. ONE SOQL: contacts for only the affected accounts
        Map<Id, List<Contact>> contactsByAcct = new Map<Id, List<Contact>>();

        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            if (!contactsByAcct.containsKey(c.AccountId)) {
                contactsByAcct.put(c.AccountId, new List<Contact>());
            }
            contactsByAcct.get(c.AccountId).add(c);
        }

        // 3. Decide which contacts to update
        List<Contact> toUpdate = new List<Contact>();

        for (Id acctId : changedAccountIds) {
            List<Contact> contacts = contactsByAcct.get(acctId);
            if (contacts == null) {
                continue;
            }

            String oldCountry = oldCountryByAcct.get(acctId);
            Account newAcc = (Account) Trigger.newMap.get(acctId);
            String newCountry = newAcc.BillingCountry;

            for (Contact c : contacts) {
                // Update only contacts whose MailingCountry is blank or still
                // equals the account's *previous* country.
                if (c.MailingCountry == null
                    || c.MailingCountry == ''
                    || c.MailingCountry == oldCountry) {
                    c.MailingCountry = newCountry;
                    toUpdate.add(c);
                }
            }
        }

        // 4. ONE DML
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
